using System;
using System.Collections;
using System.IO;
using System.Text;
using UnityEngine;

[Serializable] public sealed class LiveCampaignExpected {
 public string tripId,campaign,seed,request;public string[] lawIds;public int sequence,cash,debt,expenses,quoted,payment,start,deficit,cleanBonus,lawCount;
 public double elapsed,metres;public float remaining,arrival,wait,fuel;
}
// Two real player processes verify the shipping initializer and serializer.
// Vehicle positions and game clocks are controlled; this is not physical/manual driving.
public sealed class LiveCampaignProbe:MonoBehaviour {
 const string ExpectedPath="artifacts/live-campaign-expected.json";
 DriveSession s;bool reload;int checks;readonly StringBuilder report=new StringBuilder();
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Attach(){var args=Environment.GetCommandLineArgs();if(Array.IndexOf(args,"-liveSaveTest")>=0||Array.IndexOf(args,"-liveReloadTest")>=0)new GameObject("Live campaign process check").AddComponent<LiveCampaignProbe>();}
 void Check(bool ok,string reason){checks++;report.AppendLine((ok?"PASS ":"FAIL ")+reason);Debug.Log((ok?"PASS ":"FAIL ")+reason);if(!ok)throw new Exception(reason);}
 void Pose(int index){var stop=s.jobs.stops[index];var p=stop.Kerb+Vector3.up*.65f;var r=Quaternion.LookRotation(stop.Direction);s.taxi.body.position=p;s.taxi.body.rotation=r;s.taxi.transform.SetPositionAndRotation(p,r);Physics.SyncTransforms();}
 IEnumerator Start(){yield return new WaitForSecondsRealtime(2);s=FindObjectOfType<DriveSession>();reload=Array.IndexOf(Environment.GetCommandLineArgs(),"-liveReloadTest")>=0;bool ok=false;try{DisableObservers();if(reload)Reload();else Save();ok=true;}catch(Exception e){report.AppendLine(e.ToString());Debug.LogException(e);}Directory.CreateDirectory("artifacts");File.WriteAllText(reload?"artifacts/live-campaign-reload.txt":"artifacts/live-campaign-save.txt",report.ToString()+"\nchecks="+checks+"\n");Debug.Log("LIVE_CAMPAIGN_"+(reload?"RELOAD_":"SAVE_")+(ok?"OK":"FAILED")+" checks="+checks);Application.Quit(ok?0:1);}
 void DisableObservers(){s.business.enabled=false;s.jobs.enabled=false;s.jobs.nav.enabled=false;s.requests.enabled=false;s.law.enabled=false;s.manners.enabled=false;s.GetComponent<ServiceLawZones>().enabled=false;s.taxi.enabled=false;s.taxi.body.isKinematic=true;s.taxi.body.interpolation=RigidbodyInterpolation.None;foreach(var c in s.traffic.cars){c.Recycle();c.enabled=false;}}
 void Save(){var b=s.business;var j=s.jobs;b.settings=PrototypeSettings.ForThreeDays();b.settings.startCash=500;b.ledger=new EconomyLedger(b.settings);b.passengers.Clear();b.enabledCampaign=b.useV2=true;b.preparing=false;s.paused=false;Time.timeScale=1;j.ClearForDay();s.law.ids=new PrototypeIds("live-campaign-"+Guid.NewGuid().ToString("N"));s.law.ledger=new LawLedger();
  Check(b.ledger.UseWash("live-setup-wash"),"initial wash accrues cash500/debt1500 before passenger");j.ForcedRideCase=DrunkRideCase.Both;var o=new JobOffer{pickup=0,drop=3,fare=5000,seconds=180,requiredScore=70,distance=j.nav.Distance(j.stops[0],j.stops[3])};j.offers[0]=o;Pose(o.pickup);Check(j.Accept(0)&&j.Interact(),"real PassengerJobs accepts and boards fixed Both");s.requests.request.Accept("조용한 운행 약속 · 저장 복원 검증");j.DrunkRide.Advance(57,.8f);j.DrunkRide.Advance(3,.8f);j.trip.Tick(60);b.ledger.Advance(60,1000);Check(j.DrunkRide.Vomited&&j.Cleanliness==100,"vomit active but no premature vehicle cleaning penalty");Pose(o.drop);Check(j.Interact()&&j.DrunkRide.Waiting&&j.trip.ArrivalLocked,"first valid arrival enters sleeping wait");j.DrunkRide.Advance(16,1);b.ledger.Advance(16,0);
  var law=new LawEvent{id=s.law.ids.Next("live-observation"),tripId=s.law.tripId,day=1,occupied=true,family="저장 검증",reason="확정된 운송 관찰 복원"};law.Add("live-observation",LawVerdict.Compliant,0);s.law.ledger.Record(law);Check(b.SaveCheckpoint()&&!b.SaveFailed,"live checkpoint explicitly saved");var a=b.ledger.Account;var expected=new LiveCampaignExpected{tripId=s.law.tripId,campaign=s.law.ids.campaign,sequence=s.law.ids.sequence,seed=j.current.candidateSeed,request=s.requests.request.ResponseText(),cash=a.Cash,debt=a.Debt,expenses=a.Expense(1,null),quoted=j.trip.Fare,payment=j.RequestReward.Total,start=j.StartSatisfaction,deficit=j.StartDeficit,cleanBonus=j.CleanBonus,lawCount=s.law.ledger.Count,lawIds=Array.ConvertAll(s.law.ledger.Events,x=>x.id),elapsed=b.ledger.Elapsed,metres=b.ledger.Metres,remaining=j.trip.Remaining,arrival=j.DrunkRide.ArrivalElapsed,wait=j.DrunkRide.WaitElapsed,fuel=a.Fuel};Directory.CreateDirectory("artifacts");File.WriteAllText(ExpectedPath,JsonUtility.ToJson(expected,true));
  var stored=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(b.SavePath));Check(stored.version==3&&stored.live!=null&&stored.live.jobs.drunk.Vomited&&stored.live.jobs.drunk.WaitElapsed==16,"shipping v3 payload contains vomit and16second wake wait");Check(stored.days.active!=null&&Math.Abs(stored.days.active.elapsed-expected.elapsed)<.001,"ledger active time shares checkpoint boundary");Check(a.Cash==0&&a.Debt==1500&&a.Expense(1,"wash")==2000,"wash debt and expense retained in live account");Check(b.ledger.Rides==0&&b.passengers.Count==0,"arrival wait has not paid fare");
 }
 void Reload(){var e=JsonUtility.FromJson<LiveCampaignExpected>(File.ReadAllText(ExpectedPath));var b=s.business;var j=s.jobs;var a=b.ledger.Account;Check(b.useV2&&b.enabledCampaign&&j.trip.State==TripState.OnTrip&&j.DrunkRide.Waiting,"new process BusinessProgress restored active sleeping passenger");Check(s.paused&&Time.timeScale==0,"resume starts paused for review");Check(j.DrunkRide.Vomited&&j.DrunkRide.WaitElapsed==e.wait&&j.DrunkRide.ArrivalElapsed==e.arrival,"vomit, first arrival and16second wait unchanged");Check(s.law.tripId==e.tripId&&s.law.ids.campaign==e.campaign&&s.law.ids.sequence==e.sequence&&s.law.ledger.Count==e.lawCount,"law identities and observations preserved");Check(j.current.candidateSeed==e.seed&&j.StartDeficit==e.deficit&&j.StartSatisfaction==e.start&&j.CleanBonus==e.cleanBonus,"candidate and satisfaction draw unchanged");Check(j.RequestReward.Total==e.payment&&j.trip.Fare==e.quoted&&j.trip.Remaining==e.remaining,"arrival freeze and frozen settlement unchanged");Check(Math.Abs(b.ledger.Elapsed-e.elapsed)<.001&&Math.Abs(b.ledger.Metres-e.metres)<.001&&Math.Abs(a.Fuel-e.fuel)<.0001,"business time, distance and fuel restored together actual="+b.ledger.Elapsed+"/"+b.ledger.Metres+"/"+a.Fuel+" expected="+e.elapsed+"/"+e.metres+"/"+e.fuel);Check(a.Cash==e.cash&&a.Debt==e.debt&&a.Expense(1,null)==e.expenses,"cash/debt/expenses restored at same boundary");Check(s.requests.request.ResponseText()==e.request&&b.ledger.Rides==0&&b.passengers.Count==0,"request fulfillment restored before single settlement");
  s.paused=false;Time.timeScale=1;Pose(j.current.drop);Check(j.Interact()&&j.trip.State==TripState.Complete,"F wakes safely after saved16seconds");Check(b.ledger.Rides==1&&b.passengers.Count==1&&a.Cash-a.Debt==e.cash-e.debt+e.payment&&j.Cleanliness==10,"one fare, one result and post-vomit cleanliness10");Check(!a.Fare(e.tripId,e.payment,1)&&j.trip.Complete()==0,"saved trip cannot settle twice");Check(b.SaveCheckpoint(),"completed trip save succeeds");b.ledger.RequestClose();Check(b.ledger.Settle(),"controlled day settlement");Check(b.SaveCheckpoint()&&b.NextDay(),"next day opens from real settled account");Check(b.ledger.Day==2&&b.ledger.Care.Cleanliness==10&&b.ledger.Care.DrunksBoarded==0,"next day carries cleanliness and resets drunk boarding cap");Check(b.ledger.Account.Expense(1,"wash")==2000&&b.passengers.Count==1&&s.law.ids.campaign==e.campaign&&s.law.ids.sequence>=e.sequence,"next day preserves prior transactions, receipt and law identity");Check(b.SaveCheckpoint(),"next-day live boundary saved");var disk=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(b.SavePath));Check(disk.days.currentDay==2&&disk.days.records.Length==1&&disk.passengers.Length==1&&disk.passengers[0].tripId==e.tripId&&disk.passengers[0].paid==e.payment,"next-day disk JSON retains prior receipt and settled day");var diskAccount=CampaignAccount.Restore(disk.account);Check(diskAccount.Expense(1,"wash")==2000&&Array.FindAll(disk.account.entries,x=>x.kind=="fare").Length==1,"next-day disk JSON retains one fare and wash expense");Check(disk.ids.campaign==e.campaign&&disk.ids.sequence>=e.sequence&&disk.law.Length==e.lawCount,"next-day disk JSON retains law identity and count");foreach(string lawId in e.lawIds)Check(Array.Exists(disk.law,x=>x.id==lawId),"next-day disk law ID "+lawId);
 }
}
